from typing import Final

import pytest

DEFAULTS: Final[tuple[tuple[str, str], ...]] = (("mode", "fast"), ("level", "3"))


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys/values on DEFAULTS and return the resulting values.

    keys[i] is set to values[i]. A later pair for the same key overrides an
    earlier one. Output order is mode, level, then any other keys in the order
    they first appear in keys.
    """
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    leading = ("mode", "level")
    rest = [k for k in merged if k not in leading]
    return [merged[k] for k in (*leading, *rest)]


def test_no_overrides_returns_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_and_extra_key() -> None:
    assert settings(["color", "level"], ["red", "5"]) == ["fast", "5", "red"]


def test_extra_keys_keep_given_order() -> None:
    assert settings(["z", "a"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_duplicate_key_later_wins() -> None:
    assert settings(["x", "x"], ["1", "2"]) == ["fast", "3", "2"]


def test_settings_is_pure_across_calls() -> None:
    settings(["mode"], ["slow"])
    assert settings([], []) == ["fast", "3"]


@pytest.mark.parametrize(
    ("keys", "values", "expected"),
    [
        (["level"], ["7"], ["fast", "7"]),
        (["mode", "level"], ["x", "y"], ["x", "y"]),
    ],
)
def test_parametrized_overrides(keys: list[str], values: list[str], expected: list[str]) -> None:
    assert settings(keys, values) == expected
